                      word == "three" || word == "four" || word == "five" || 
                      word == "six" || word == "seven" || word == "eight" || 
                      word == "nine")

method IsSortedOutput(output: string, input: string) returns (isSorted: bool)
    // This method checks that the output string contains all the numbers from the input
    // in sorted order.
    ensures isSorted == (output == "" || IsSortedList(output.Split(" ")) && ContainsAllNumbers(output, input))

method IsSortedList(list: seq<string>) returns (sorted: bool)
    // This method checks if the list is sorted in order.
    ensures sorted == (list.Length <= 1 || forall i: int :: 0 <= i < list.Length - 1 ==> list[i] <= list[i + 1])

method ContainsAllNumbers(output: string, input: string) returns (containsAll: bool)
    // This method checks that all words in the input are present in the output.
    ensures containsAll == forall word: string :: word in input.Split(" ") ==> word in output.Split(" ")
